    precision: usize,

pub fn format(self: @This(), writer: *std.Io.Writer) !void {
            const whole = @trunc(self.num);
            _ = try writer.print("{d}", .{ whole });
            const rem = (self.num - whole);
            if ((rem != 0)) {
                const buf_len = (2 + precision);
                var buf: [buf_len]u8 = undefined;
                _ = &buf;
                const fmt_str = (comptime std.fmt.comptimePrint("{{d:.{d}}}", .{ precision }));
                var formatted = ((std.fmt.bufPrint((&buf), fmt_str, .{ rem })) catch unreachable);
                _ = &formatted;
                formatted = formatted[2..];
                const trimmed = std.mem.trimRight(u8, formatted, "0");
                _ = try writer.print(".{s}", .{ trimmed });
            }
    }
};
}

pub fn trimmedPrecision(value: f64, comptime precision: usize) TrimmedPrecisionFormatter(precision) {
        const Formatter = TrimmedPrecisionFormatter(precision);
        return Formatter{ .num = value, .precision = precision };
}

pub fn formatDurationOneDecimal(data: FormatDurationData, writer: *std.Io.Writer) !void {
        var buf: [24]u8 = undefined;
        _ = &buf;
        var fbs = std.io.fixedBufferStream((&buf));
        _ = &fbs;
        var buf_writer = fbs.writer();
        _ = &buf_writer;
        if (data.negative) {
            _ = ((buf_writer.writeByte(45)) catch unreachable);
        }
        var ns_remaining = data.ns;
        _ = &ns_remaining;
        inline for (duration_major_units) |unit| {
            if ((ns_remaining >= unit.ns)) {
                const units = (ns_remaining / unit.ns);
                _ = ((buf_writer.print("{d}", .{ units })) catch unreachable);
                _ = ((buf_writer.writeByte(unit.sep)) catch unreachable);
                ns_remaining = (ns_remaining - (units * unit.ns));
                if ((ns_remaining == 0)) {
                    return writer.writeAll(fbs.getWritten());
                }
            }
        }
        inline for (duration_minor_units) |unit| {
            const kunits = ((ns_remaining * 1000) / unit.ns);
            if ((kunits >= 1000)) {
                _ = ((buf_writer.print("{d}", .{ (kunits / 1000) })) catch unreachable);
                const frac = @divFloor((kunits % 1000), 100);
                if ((frac > 0)) {
                    var decimal_buf: [2]u8 = .{ 46, 0 };
                    _ = &decimal_buf;
                    _ = std.fmt.printInt(decimal_buf[1..], frac, 10, .lower, .{ .fill = 48, .width = 1 });
                    _ = ((buf_writer.writeAll((&decimal_buf))) catch unreachable);
                }
                _ = ((buf_writer.writeAll(unit.sep)) catch unreachable);
                return writer.writeAll(fbs.getWritten());
            }
        }
        _ = ((buf_writer.print("{d}", .{ ns_remaining })) catch unreachable);
        _ = ((buf_writer.writeAll("ns")) catch unreachable);
        return writer.writeAll(fbs.getWritten());
}

pub fn fmtDurationOneDecimal(ns: u64) std.fmt.Alt(FormatDurationData,formatDurationOneDecimal) {
        return .{ .data = FormatDurationData{ .ns = ns } };
}

pub fn fmtSlice(data: anytype, comptime delim: []const u8) FormatSlice(@TypeOf(data),delim) {
        return .{ .slice = data };
}

pub fn FormatSlice(comptime T: type, comptime delim: []const u8) type {
        return struct {
    slice: T,

pub fn format(self: @This(), writer: *std.Io.Writer) !void {
            if ((self.slice.len == 0)) {
                return;
            }
            const f: []const u8 = "{s}";
            _ = try writer.print(f, .{ self.slice[0] });
            for (cp_iter_slice(self.slice[1..])) |item| {
                _ = &item;
                if ((delim.len > 0)) {
                    _ = try writer.writeAll(delim);
                }
                _ = try writer.print(f, .{ item });
            }
    }
};
}

pub fn double(number: f64) FormatDouble {
        return .{ .number = number };
}

pub fn nullableFallback(value: anytype, null_fallback: []const u8) NullableFallback(@TypeOf(value)) {
        return .{ .value = value, .null_fallback = null_fallback };
}

pub fn NullableFallback(comptime T: type) type {
        return struct {
    value: T,
    null_fallback: []const u8,

pub fn format(self: @This(), writer: *std.Io.Writer) !void {
            if (self.value) |value| {
                _ = &value;
                _ = try writer.print("{}", .{ value });
            } else {
                _ = try writer.writeAll(self.null_fallback);
            }
    }
};
}

pub fn escapePowershell(str: []const u8) std.fmt.Alt(string,escapePowershellImpl) {
        return .{ .data = str };
}

pub fn escapePowershellImpl(str: []const u8, writer: *std.Io.Writer) !void {
        var remain: []const u8 = str;
        _ = &remain;
        while (bun.strings.indexOfAny(remain, "\"`")) |i| {
            _ = try writer.writeAll(remain[0..i]);
            _ = try writer.writeAll("`");
            _ = try writer.writeByte(remain[@as(usize, @intCast(i))]);
            remain = remain[(i + 1)..];
        }
        _ = try writer.writeAll(remain);
}

pub fn NewOutOfRangeFormatter(comptime T: type) type {
        return struct {
    value: T,
    min: i64 = std.math.maxInt(i64),
    max: i64 = std.math.maxInt(i64),
    field_name: []const u8,
    msg: []const u8 = "",

pub fn format(self: @This(), writer: *std.Io.Writer) !void {
            if ((self.field_name.len > 0)) {
                _ = try writer.writeAll("The value of \"");
                _ = try writer.writeAll(self.field_name);
                _ = try writer.writeAll("\" is out of range. It must be ");
            } else {
                if (comptime Environment.isDebug) {
                    _ = @panic("Set field_name plz");
                }
                _ = try writer.writeAll("The value is out of range. It must be ");
            }
            const min = self.min;
            const max = self.max;
            const msg = self.msg;
            if (((min != std.math.maxInt(i64)) and (max != std.math.maxInt(i64)))) {
                _ = try writer.print(">= {d} and <= {d}.", .{ min, max });
            } else {
                if ((min != std.math.maxInt(i64))) {
                    _ = try writer.print(">= {d}.", .{ min });
                } else {
                    if ((max != std.math.maxInt(i64))) {
                        _ = try writer.print("<= {d}.", .{ max });
                    } else {
                        if ((msg.len > 0)) {
                            _ = try writer.writeAll(msg);
                            _ = try writer.writeByte(46);
                        } else {
                            _ = try writer.writeAll("within the range of values for type ");
                            _ = try writer.writeAll((comptime @typeName(T)));
                            _ = try writer.writeAll(".");
                        }
                    }
                }
            }
            if (comptime ((T == f64) or (T == f32))) {
                _ = try writer.print(" Received {f}", .{ double(self.value) });
            } else {
                if (comptime (T == string)) {
                    _ = try writer.print(" Received {s}", .{ self.value });
                } else {
                    if (comptime std.meta.hasFn(@TypeOf(self.value), "format")) {
                        _ = try writer.print(" Received {f}", .{ self.value });
                    } else {
                        _ = try writer.print(" Received {}", .{ self.value });
                    }
                }
            }
    }
};
}

pub fn OutOfRangeFormatter(comptime T: type) type {
        if (((T == f64) or (T == f32))) {
            return DoubleOutOfRangeFormatter;
        } else {
            if ((T == ConstU8Slice)) {
                return StringOutOfRangeFormatter;
            } else {
                if ((T == bun.String)) {
                    return BunStringOutOfRangeFormatter;
                }
            }
        }
        return IntOutOfRangeFormatter;
}

pub fn outOfRange(value: anytype, options: OutOfRangeOptions) OutOfRangeFormatter(@TypeOf(value)) {
        return .{ .value = value, .min = options.min, .max = options.max, .field_name = options.field_name, .msg = options.msg };
}

pub fn truncatedHash32(int: u64) std.fmt.Alt(u64,truncatedHash32Impl) {
        return .{ .data = int };
}

pub fn truncatedHash32Impl(int: u64, writer: *std.Io.Writer) !void {
        const in_bytes = std.mem.asBytes((&int));
        const chars: []const u8 = "0123456789abcdefghjkmnpqrstvwxyz";
        const out_bytes: [8]u8 = .{ chars[@as(usize, @intCast((in_bytes[0] & 31)))], chars[@as(usize, @intCast((in_bytes[1] & 31)))], chars[@as(usize, @intCast((in_bytes[2] & 31)))], chars[@as(usize, @intCast((in_bytes[3] & 31)))], chars[@as(usize, @intCast((in_bytes[4] & 31)))], chars[@as(usize, @intCast((in_bytes[5] & 31)))], chars[@as(usize, @intCast((in_bytes[6] & 31)))], chars[@as(usize, @intCast((in_bytes[7] & 31)))] };
        _ = try writer.writeAll((&out_bytes));
}
